fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn h(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn r(s:&str)->String{format!("{R}/{s}")}
fn eq(x:f64,y:f64){assert!((x-y).abs()<=1e-12*x.abs().max(y.abs()).max(1.));}fn med(v:&[f64])->f64{let mut v=v.to_vec();v.sort_by(f64::total_cmp);v[v.len()/2]}fn stats(v:&[f64],a:&Value){assert_eq!(v.len(),15);let mut v2=v.to_vec();v2.sort_by(f64::total_cmp);eq(v2[3],a["low"].as_f64().unwrap());eq(v2[7],a["median"].as_f64().unwrap());eq(v2[11],a["high"].as_f64().unwrap());assert_eq!(v.iter().filter(|&&x|x<1.).count(),a["wins"].as_u64().unwrap()as usize);for(i,x)in v.iter().enumerate(){eq(*x,a["ratios"][i].as_f64().unwrap());}}

