assert_eq!(callers,444);assert_eq!(timed.len(),405);let mut failed=vec![];let mut ratios=BTreeMap::new();for row in a["rows"].as_array().unwrap(){let context=row["context"].as_str().unwrap();let mut times=BTreeMap::new();for arm in["frozen","OFF","ON"]{let mut t=vec![];let mut cpu=vec![];let mut maxrss=0f64;for b in 0..15{let raw=&timed[&(context.into(),arm.into(),b)];assert_eq!(raw["rounds_per_worker"],4096);for other in["frozen","OFF","ON"]{let q=&timed[&(context.into(),other.into(),b)];assert_eq!(raw["output_sha256"],q["output_sha256"]);assert_eq!(raw["scratch_capacity_bytes_by_worker"],q["scratch_capacity_bytes_by_worker"]);}t.push(raw["elapsed_ns"].as_f64().unwrap()/4096.);cpu.push((raw["usage"]["user_cpu_ms"].as_f64().unwrap()+raw["usage"]["system_cpu_ms"].as_f64().unwrap())/4096.);maxrss=maxrss.max(raw["usage"]["whole_process_maxrss_kib"].as_f64().unwrap()/1024.);assert_eq!(raw["scratch_capacity_bytes_by_worker"][0],row["scratch_capacity_bytes_first_worker"][arm]);}eq(med(&t),row["median_ns_per_wave"][arm].as_f64().unwrap());eq(med(&cpu),row["CPU_ms_per_wave"][arm].as_f64().unwrap());eq(maxrss,row["counter_RSS_MiB_diagnostic"][arm].as_f64().unwrap());times.insert(arm,t);}
for(n,d)in[("OFF","frozen"),("ON","frozen"),("ON","OFF")]{let v=times[n].iter().zip(&times[d]).map(|(n,d)|n/d).collect::<Vec<_>>();let report=&row["pairs"][format!("{n}/{d}")];stats(&v,report);let pass=if n=="OFF"{report["low"].as_f64().unwrap()>=1./1.03&&report["high"].as_f64().unwrap()<=1.03}else{report["high"].as_f64().unwrap()<=1.03};if !pass{failed.push(format!("{context}/{n}/{d}/{}",if n=="OFF"{"calibration"}else{"nonregression"}));}if context.starts_with("G2-")&&context.ends_with("-w32")&&n=="ON"&&(report["high"].as_f64().unwrap()>=1.||report["wins"].as_u64().unwrap()<10){failed.push(format!("{context}/ON/{d}/gain"));}ratios.insert(format!("{context}/{n}/{d}"),v);}}
